import os
import time
import requests

def get_datadog_metric_aggregation(metric_name, aggregation="avg", window_seconds=3600, tags=None):
    api_key = os.environ.get("DD_API_KEY")
    app_key = os.environ.get("DD_APP_KEY")
    if not api_key or not app_key:
        raise ValueError("DD_API_KEY and DD_APP_KEY environment variables must be set")

    to_ts = int(time.time())
    from_ts = to_ts - window_seconds

    tag_clause = "{*}" if tags is None else "{" + ",".join(tags) + "}"
    query = f"{aggregation}:{metric_name}{tag_clause}"

    url = "https://api.datadoghq.com/api/v2/query/scalar"
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key
    }
    payload = {
        "data": {
            "type": "scalar_request",
            "attributes": {
                "query": query,
                "from": from_ts,
                "to": to_ts
            }
        }
    }

    response = requests.post(url, json=payload, headers=headers)
    response.raise_for_status()
    return response.json()
